using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Windows.Forms;using System.Drawing;using V15Voice;
public static class AnchoredUiTests {
 static int count,code;static object Field(object f,string n){return f.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(f);}static object Call(object f,string n,params object[] args){return f.GetType().GetMethod(n,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(f,args);}static void Check(bool yes,string n){if(!yes)throw new Exception("FAIL "+n);Console.WriteLine("PASS "+n);count++;}
 static void Capture(Form f,string file){f.Refresh();Application.DoEvents();using(var image=new Bitmap(f.Width,f.Height)){using(var g=Graphics.FromImage(image))g.CopyFromScreen(f.Location,Point.Empty,f.Size);image.Save(Path.Combine(Path.GetTempPath(),file));}}
 [STAThread]public static void Main(){Application.EnableVisualStyles();var f=new MainForm();f.Shown+=(sender,eventArgs)=>{var timer=new Timer{Interval=250};timer.Tick+=(s,e)=>{timer.Stop();try{var mode=(ComboBox)Field(f,"mode");var grid=(DataGridView)Field(f,"grid");var batch=(ComboBox)Field(f,"batchMode");var info=(Label)Field(f,"info");Check(mode.Items.Count==3&&mode.Items[2].ToString().Contains("V15.6"),"Third timeline mode exposes V15.6");Check(batch.Items.Count==4&&batch.Items[3].ToString().Contains("V15.6"),"Queue exposes explicit V15.6 override");mode.SelectedIndex=2;Check(grid.Columns[6].Visible&&!grid.Columns[4].Visible,"Hard anchor checkbox replaces word count in new mode");Check(((Button)Field(f,"rhythmMeasure")).Text.Contains("tất cả chặng"),"Measure control uses stages, not five legacy cues");Check(!((CheckBox)Field(f,"slow")).Enabled&&!((CheckBox)Field(f,"joinSentences")).Enabled,"Legacy sentence join and short-cue slowdown do not override stage fitting");Check(info.Text.Contains("V15.6")&&!info.Text.Contains(">10"),"New mode summary has no ten-word warning");
  ((ComboBox)Field(f,"breathMode")).SelectedIndex=2;var o=(RenderOptions)Call(f,"Options");Check(o.Anchored&&!o.Locked&&o.AnchorAlignment==null,"New mode routes renderer and defaults to WAV only");Check(((KokoroEngine)Call(f,"NewEngine")).Archive!=null,"New mode reuses persistent speech cache");grid.Rows[0].Cells[6].Value=true;Call(f,"ReadGrid");Check(((List<Cue>)Field(f,"cues"))[0].AnchorAfter,"Checkbox reaches source cue anchor");var text=Scripts.ToSrt((List<Cue>)Field(f,"cues"));Check(AnchoredVoice.Plan((List<Cue>)Field(f,"cues")).Count>=2,"Checkbox creates a hard stage boundary");Call(f,"Populate");Check(Convert.ToBoolean(grid.Rows[0].Cells[6].Value),"Anchor survives grid refresh");
  ((CheckBox)Field(f,"anchoredSrt")).Checked=true;o=(RenderOptions)Call(f,"Options");Check(o.AnchorAlignment!=null,"Optional SRT uses measured alignment callback");var settings=(VoiceSettings)Call(f,"CaptureSettings");Check(settings.Mode==2&&settings.AnchorSrt,"New settings captured");mode.SelectedIndex=0;((CheckBox)Field(f,"anchoredSrt")).Checked=false;Call(f,"Apply",settings);Check(mode.SelectedIndex==2&&((CheckBox)Field(f,"anchoredSrt")).Checked,"New settings restore correctly");
  string source=Path.Combine(Path.GetTempPath(),"v1411-ui-"+Guid.NewGuid().ToString("N")+".srt");File.WriteAllText(source,text);Call(f,"LoadFile",source);Check(mode.SelectedIndex==2,"Opening SRT preserves chosen V15.6 mode");grid.Rows[1].Cells[6].Value=true;Call(f,"ReadGrid");Call(f,"LoadFile",source);Check(((List<Cue>)Field(f,"cues"))[1].AnchorAfter,"Reopening unchanged source restores manual anchors");File.AppendAllText(source,"\n\n4\n00:00:11,000 --> 00:00:15,000\nThe source has now changed.\n");Call(f,"LoadFile",source);Check(!((List<Cue>)Field(f,"cues"))[1].AnchorAfter,"Changed source cannot inherit stale anchors");
  batch.SelectedIndex=3;settings=(VoiceSettings)Call(f,"CaptureSettings");batch.SelectedIndex=0;Call(f,"Apply",settings);Check(batch.SelectedIndex==3,"Explicit anchored queue choice persists");Call(f,"AddFiles",(object)new string[]{source});Call(f,"EditQueued");Check(mode.SelectedIndex==2&&Field(f,"editingJob")!=null,"Editing queued SRT preserves new mode");grid.Rows[0].Cells[6].Value=true;Call(f,"ReadGrid");Call(f,"SaveSession");var jobs=QueueStore.Load(Path.Combine((string)Field(f,"stateDir"),"queue.xml"));Check(jobs.Single().Cues[0].AnchorAfter,"Queue anchor survives saved session");
  var tabs=(TabControl)Field(f,"tabs");tabs.SelectedIndex=0;var panel=(FlowLayoutPanel)Field(f,"anchoredControls");((ScrollableControl)panel.Parent).ScrollControlIntoView(panel);Application.DoEvents();Check(panel.Visible&&panel.Parent!=null,"Anchor controls reachable inside settings scroll panel");Capture(f,"v1411-anchor-ui.png");Call(f,"SetBusy",true);Check(!panel.Enabled&&grid.ReadOnly&&!batch.Enabled,"Anchor editing and queue options locked while rendering");Call(f,"SetBusy",false);Check(panel.Enabled&&!grid.ReadOnly,"Controls unlock after task completes");
  mode.SelectedIndex=0;Check(!grid.Columns[6].Visible&&grid.Columns[4].Visible,"Legacy mode retains existing columns");Call(f,"RefreshProse");Check(!((RenderOptions)Call(f,"Options")).Anchored,"Legacy locked renderer remains selectable");mode.SelectedIndex=1;Check(!((RenderOptions)Call(f,"Options")).Anchored,"Legacy flexible renderer remains selectable");
  string txt=Path.ChangeExtension(source,".txt");File.WriteAllText(txt,"A natural paragraph has no source timeline.");Call(f,"LoadFile",txt);Check((bool)Field(f,"proseInput")&&mode.SelectedIndex==1&&!mode.Enabled,"TXT retains natural mode rather than inventing source duration");Check(!((RenderOptions)Call(f,"Options")).Anchored&&!grid.Columns[6].Visible,"TXT never uses hard stage renderer");
  Console.WriteLine("TOTAL ANCHORED UI "+count+" passed.");}catch(Exception ex){Console.WriteLine(ex);code=1;}finally{f.Close();}};timer.Start();};Application.Run(f);Environment.Exit(code);}
}
